/**
 * CORE-6258 — improvement requests (doc2-api
 * `/v3/validation-assistant/improvements`). A user who may not change a rule
 * suggests the change from the explainer card; an admin decides on the Touchless
 * dashboard. Everything here is plain data; text is rendered as text nodes only.
 */
import {
  parseExplainer,
  type Explainer,
  type ExplainerStage,
} from 'src/utils/validationAssistant/explainer';

export type ImprovementStatus = 'pending' | 'approved' | 'rejected' | 'expired';
export type ImprovementOutcomeState =
  | 'pending'
  | 'measuring'
  | 'verified'
  | 'no_effect';

export const REJECT_REASONS = [
  'not_needed',
  'wrong_suggestion',
  'handled_otherwise',
  'other',
] as const;
export type RejectReason = (typeof REJECT_REASONS)[number];

/** Server limit of the reject note. */
export const REJECT_NOTE_MAX = 500;

export interface ImprovementOutcome {
  state: ImprovementOutcomeState;
  corrections_saved: number | null;
  rate_before: number | null;
  rate_after: number | null;
  measured_on: string | null;
  /**
   * Which rate the before/after numbers are (CORE-6267): the AP touchless rate
   * (pure + AP touchless) or, for rows measured before that, the pure rate.
   * `null` when the server does not say — then the label stays neutral.
   */
  basis: 'ap' | 'pure' | null;
  corrections_per_100_before: number | null;
  corrections_per_100_after: number | null;
}

export interface ImprovementRequest {
  id: string;
  status: ImprovementStatus;
  offer_kind: string;
  doc_type: string;
  target_field: string;
  field_label: string;
  title: string;
  sections: { kind: string; text: string }[];
  request_count: number;
  requested_by_me: boolean;
  example_doc_ids: string[];
  evidence: Record<string, unknown> | null;
  touchless_impact: Record<string, unknown> | null;
  created_on: string | null;
  decided_on: string | null;
  decision_reason_code: string | null;
  decision_note: string | null;
  created_rule_id: string | null;
  activated: boolean;
  outcome: ImprovementOutcome | null;
  /** Admin detail only: the fresh dry run of what approving would do. */
  admin_preview: Record<string, unknown> | null;
  /** The full explainer snapshot, when the server sends it (scenes + diagram). */
  explainer: unknown;
  /** Admin-only document context. Supplier identity is not a rule condition. */
  request_context: {
    supplier: { id: string | null; name: string | null } | null;
    rule_scope: 'manual_review' | 'document_type' | 'conditional' | 'unknown';
    sub_org_id: string | null;
  } | null;
  can_approve: boolean;
}

export interface DocumentRequestStatus {
  offer_id: string;
  request_id: string;
  status: ImprovementStatus;
  requested_on: string | null;
  decided_on: string | null;
  decision_reason_code: string | null;
  decision_note: string | null;
}

const STATUSES: readonly string[] = [
  'pending',
  'approved',
  'rejected',
  'expired',
];
const OUTCOME_STATES: readonly string[] = [
  'pending',
  'measuring',
  'verified',
  'no_effect',
];

function str(value: unknown): string | null {
  return typeof value === 'string' && value.trim() ? value : null;
}

function numOrNull(value: unknown): number | null {
  return typeof value === 'number' && Number.isFinite(value) ? value : null;
}

function record(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null;
}

function parseOutcome(value: unknown): ImprovementOutcome | null {
  const v = record(value);
  if (!v || !OUTCOME_STATES.includes(String(v.state))) return null;
  return {
    state: v.state as ImprovementOutcomeState,
    corrections_saved: numOrNull(v.corrections_saved),
    rate_before: numOrNull(v.rate_before),
    rate_after: numOrNull(v.rate_after),
    measured_on: str(v.measured_on),
    basis: outcomeBasis(v),
    corrections_per_100_before: numOrNull(v.corrections_per_100_before),
    corrections_per_100_after: numOrNull(v.corrections_per_100_after),
  };
}

/** `basis`, else the prefix of `measurement_version` ("ap_..." / "pure_..."). */
function outcomeBasis(v: Record<string, unknown>): 'ap' | 'pure' | null {
  const basis = String(v.basis ?? '').toLowerCase();
  if (basis === 'ap' || basis === 'pure') return basis;
  const version = String(v.measurement_version ?? '').toLowerCase();
  if (version.startsWith('ap_')) return 'ap';
  if (version.startsWith('pure_')) return 'pure';
  return null;
}

export function parseRequest(value: unknown): ImprovementRequest | null {
  const v = record(value);
  const id = str(v?.id);
  if (!v || !id || !STATUSES.includes(String(v.status))) return null;
  const sections = Array.isArray(v.sections)
    ? v.sections
        .map((s) => ({
          kind: str(record(s)?.kind),
          text: str(record(s)?.text),
        }))
        .filter(
          (s): s is { kind: string; text: string } => !!s.kind && !!s.text,
        )
    : [];
  return {
    id,
    status: v.status as ImprovementStatus,
    offer_kind: str(v.offer_kind) ?? '',
    doc_type: str(v.doc_type) ?? '',
    target_field: str(v.target_field) ?? '',
    field_label: str(v.field_label) ?? '',
    title: str(v.title) ?? str(v.field_label) ?? '',
    sections,
    request_count: numOrNull(v.request_count) ?? 1,
    requested_by_me: v.requested_by_me === true,
    example_doc_ids: Array.isArray(v.example_doc_ids)
      ? v.example_doc_ids.filter((d): d is string => typeof d === 'string')
      : [],
    evidence: record(v.evidence),
    touchless_impact: record(v.touchless_impact),
    created_on: str(v.created_on),
    decided_on: str(v.decided_on),
    decision_reason_code: str(v.decision_reason_code),
    decision_note: str(v.decision_note),
    created_rule_id: str(v.created_rule_id),
    activated: v.activated === true,
    outcome: parseOutcome(v.outcome),
    admin_preview: record(v.admin_preview),
    explainer: v.explainer ?? v.explainer_snapshot ?? null,
    request_context: parseRequestContext(v.request_context),
    // Compatibility with older API releases; decisions are never executable.
    can_approve:
      v.can_approve === true ||
      (v.can_approve === undefined &&
        ['transformation', 'lookup'].includes(String(v.offer_kind))),
  };
}

function parseRequestContext(
  value: unknown,
): ImprovementRequest['request_context'] {
  const v = record(value);
  if (!v) return null;
  const supplier = record(v.supplier);
  const scope = str(v.rule_scope);
  return {
    supplier: supplier
      ? { id: str(supplier.id), name: str(supplier.name) }
      : null,
    sub_org_id: str(v.sub_org_id),
    rule_scope: ['manual_review', 'document_type', 'conditional'].includes(
      scope ?? '',
    )
      ? (scope as 'manual_review' | 'document_type' | 'conditional')
      : 'unknown',
  };
}

/** Only local UUID document routes, never URLs supplied by a request. */
export function exampleDocumentLink(id: string): string | null {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
    id,
  )
    ? `/field_validation_v1/${id}`
    : null;
}

export function parseRequests(value: unknown): ImprovementRequest[] {
  if (!Array.isArray(value)) return [];
  return value
    .map(parseRequest)
    .filter((r): r is ImprovementRequest => r !== null);
}

export function parseDocumentStatuses(value: unknown): DocumentRequestStatus[] {
  if (!Array.isArray(value)) return [];
  const out: DocumentRequestStatus[] = [];
  for (const item of value) {
    const v = record(item);
    const offerId = str(v?.offer_id);
    const requestId = str(v?.request_id);
    if (!v || !offerId || !requestId || !STATUSES.includes(String(v.status))) {
      continue;
    }
    out.push({
      offer_id: offerId,
      request_id: requestId,
      status: v.status as ImprovementStatus,
      requested_on: str(v.requested_on) ?? str(v.created_on),
      decided_on: str(v.decided_on),
      decision_reason_code: str(v.decision_reason_code),
      decision_note: str(v.decision_note),
    });
  }
  return out;
}

const STAGE_BY_KIND: Record<string, ExplainerStage> = {
  transformation: 'transformation',
  lookup: 'lookup',
  custom_validation: 'validation',
};

/**
 * The explainer the drawer shows for a request. The full snapshot (scenes +
 * diagram) when the server sends it; otherwise one built from the request's own
 * title, sections, evidence and impact — no diagram example, no scenes, so no
 * player. It never offers "apply": the dashboard's own buttons decide.
 */
export function requestToExplainer(
  request: ImprovementRequest,
  audioToken: string | null = null,
): Explainer | null {
  const snapshot = record(request.explainer);
  const base = {
    id: `req_${request.id}`,
    offer_id: `req:${request.id}`,
    offer_kind: request.offer_kind,
    field: request.target_field,
    field_label: request.field_label,
    title: request.title,
    sections: request.sections,
    diagram: {
      stages: [],
      active_stage: STAGE_BY_KIND[request.offer_kind] ?? 'transformation',
      example: null,
    },
    evidence: request.evidence,
    touchless_impact: request.touchless_impact,
    scenes: [],
    audio: { available: false },
  };
  const merged: Record<string, unknown> = {
    ...base,
    ...(snapshot ?? {}),
    id: base.id,
    can_apply: false,
    apply_ref: null,
    audio: audioToken
      ? { available: true, token: audioToken }
      : { available: false },
  };
  // a snapshot without a usable diagram keeps the derived one
  const parsed = parseExplainer(merged);
  if (parsed) return parsed;
  return parseExplainer({ ...merged, diagram: base.diagram });
}

/** Reject needs a note only for "other"; the server enforces the same. */
export function rejectIsValid(reason: string, note: string): boolean {
  if (!(REJECT_REASONS as readonly string[]).includes(reason)) return false;
  if (note.length > REJECT_NOTE_MAX) return false;
  return reason !== 'other' || note.trim().length > 0;
}

/** Whole days since `iso`, never negative; null when unparsable. */
export function ageInDays(
  iso: string | null,
  now: number = Date.now(),
): number | null {
  if (!iso) return null;
  const t = new Date(iso).getTime();
  if (Number.isNaN(t)) return null;
  return Math.max(0, Math.floor((now - t) / 86_400_000));
}

/** "up to +9.0 pp" gain of the request's Touchless impact, or null. */
export function impactDeltaPp(request: ImprovementRequest): number | null {
  return numOrNull(request.touchless_impact?.delta_pp);
}
