/**
 * CORE-6235 — client for the explainer's narration (doc2-api
 * `POST /v3/validation-assistant/explainer/audio`, `GET .../audio/{audio_id}`).
 *
 * The POST starts (or finds) the narration for a token and is polled until it
 * is ready; the GET returns the mp3, which needs the auth header, so it is
 * fetched as a blob and played from an object URL. Same raw `fetch` + token
 * the chat stream uses.
 */
import { getAuthorizationToken } from 'src/pages/APIs';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { OpenAPI } from 'src/generated-api-sdk/core/OpenAPI';
import {
  parseExplainers,
  type AudioTiming,
  type Explainer,
} from 'src/utils/validationAssistant/explainer';

/** Contract: the narration is a few hundred KB; anything above 5 MB is not it. */
export const EXPLAINER_AUDIO_MAX_BYTES = 5 * 1024 * 1024;

export const EXPLAINER_IMPROVEMENTS_PATH =
  '/v3/validation-assistant/explainer/improvements';

export const EXPLAINER_AUDIO_PATH = '/v3/validation-assistant/explainer/audio';

export class ExplainerAudioError extends Error {
  status: number;
  constructor(message: string, status = 0) {
    super(message);
    this.name = 'ExplainerAudioError';
    this.status = status;
  }
}

async function authHeaders(): Promise<Record<string, string>> {
  const token = await getAuthorizationToken();
  const orgId = getOrgId();
  return {
    Authorization: token || '',
    ...(orgId ? { 'X-ORG-ID': orgId } : {}),
  };
}

function isTiming(value: unknown): value is AudioTiming {
  const status = (value as { status?: unknown } | null)?.status;
  return status === 'pending' || status === 'ready' || status === 'failed';
}

export const validationAssistantExplainerService = {
  /**
   * CORE-6249 — the improvements of one document (doc2-api
   * `GET .../explainer/improvements`), proactively, without a question. The
   * server sends the safe projection (no audio token, no apply reference), so
   * these are teasers only; the full explainer with audio comes from the chat.
   * 403 (assistant off for the org) and 404 (document not visible) are "none".
   */
  async getImprovements(
    docId: string,
    language: string,
    signal?: AbortSignal,
  ): Promise<Explainer[]> {
    // CORE-6307: the "apply to this document" set_value card of each offer
    const query = new URLSearchParams({
      doc_id: docId,
      language,
      include_form_actions: 'true',
    });
    const response = await fetch(
      `${OpenAPI.BASE}${EXPLAINER_IMPROVEMENTS_PATH}?${query.toString()}`,
      { method: 'GET', headers: await authHeaders(), signal },
    );
    if (response.status === 403 || response.status === 404) return [];
    if (!response.ok) {
      throw new ExplainerAudioError(`HTTP ${response.status}`, response.status);
    }
    const body = (await response.json()) as { explainers?: unknown } | null;
    return parseExplainers(body?.explainers);
  },

  /** Starts or finds the narration; poll again while `status` is "pending". */
  async requestAudio(token: string, signal?: AbortSignal): Promise<AudioTiming> {
    const response = await fetch(`${OpenAPI.BASE}${EXPLAINER_AUDIO_PATH}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...(await authHeaders()) },
      body: JSON.stringify({ token }),
      signal,
    });
    if (!response.ok) {
      throw new ExplainerAudioError(`HTTP ${response.status}`, response.status);
    }
    const body: unknown = await response.json();
    if (!isTiming(body)) throw new ExplainerAudioError('bad response');
    return body;
  },

  async fetchAudioBlob(audioId: string, signal?: AbortSignal): Promise<Blob> {
    const response = await fetch(
      `${OpenAPI.BASE}${EXPLAINER_AUDIO_PATH}/${encodeURIComponent(audioId)}`,
      { method: 'GET', headers: await authHeaders(), signal },
    );
    if (!response.ok) {
      throw new ExplainerAudioError(`HTTP ${response.status}`, response.status);
    }
    const length = Number(response.headers?.get?.('content-length') ?? 0);
    if (length > EXPLAINER_AUDIO_MAX_BYTES) {
      throw new ExplainerAudioError('audio too large');
    }
    const blob = await response.blob();
    if (blob.size > EXPLAINER_AUDIO_MAX_BYTES) {
      throw new ExplainerAudioError('audio too large');
    }
    return blob;
  },
};

export default validationAssistantExplainerService;
