      <q-btn
        flat
        dense
        no-caps
        color="primary"
        :icon="phase === 'idle' ? 'volume_up' : 'stop'"
        :label="
          $t(
            `validation_assistant_visual_${phase === 'idle' ? 'listen' : 'stop'}`,
          )
        "
        :aria-busy="phase === 'loading'"
        data-test="validation-assistant-explainer-listen"
        @click="phase === 'idle' ? play() : stop()"
      />
      <span v-if="phase === 'loading'" role="status">{{
        $t('validation_assistant_visual_loading')
      }}</span>
    </div>
    <dl class="expl-image__rows">
      <div
        v-for="row in visual.rows"
        :key="row.id"
        class="expl-image__row"
        :class="{
