            !!row.scene && row.scene === currentScene?.id,
        }"
        :data-row-id="row.id"
        :data-scene="row.scene"
        data-test="validation-assistant-explainer-image-row"
      >
        <dt class="expl-image__label">
          {{ $t(`validation_assistant_visual_${row.kind}`) }}
        </dt>
        <dd>
          <div
            v-if="row.kind === 'expected_actual'"
            class="expl-image__comparison"
          >
            <div class="expl-image__value expl-image__value--good">
