              <strong>{{ $t('validation_assistant_visual_before') }}</strong
              ><s>{{ row.before }}</s>
            </div>
            <div class="expl-image__value expl-image__value--good">
              <strong>{{ $t('validation_assistant_visual_after') }}</strong
              >{{ row.after }}
            </div>
          </div>
          <div
            v-else-if="
              row.kind === 'evidence' && visual.template === 'explain_rule'
            "
            class="expl-image__evidence"
          >
            <span>{{ evidenceSummary(row) }}</span>
            <div class="expl-image__meter" aria-hidden="true">
              <i
                v-for="(exception, index) in evidenceMeter(row)"
                :key="index"
                :class="{ 'expl-image__meter--exception': exception }"
              />
            </div>
          </div>
          <ol v-else-if="row.kind === 'flow'" class="expl-image__flow">
            <li
