<script lang="ts">
import { defineComponent, toRef, type PropType } from 'vue';
import {
  EXPLAINER_STAGES,
  type Explainer,
} from 'src/utils/validationAssistant/explainer';
import type {
  ExplainerImageData,
  VisualRow,
} from 'src/utils/validationAssistant/explainerVisual';
import { useExplainerNarration } from 'src/composables/validationAssistant/useExplainerNarration';
export default defineComponent({
  name: 'ExplainerImage',
  props: {
    explainer: { type: Object as PropType<Explainer>, required: true },
    visual: { type: Object as PropType<ExplainerImageData>, required: true },
  },
  setup(props) {
    return {
      ...useExplainerNarration(toRef(props, 'explainer')),
    };
  },
  methods: {
    stageLabel(key: string): string {
      return (EXPLAINER_STAGES as readonly string[]).includes(key)
        ? String(this.$t(`validation_assistant_explainer_stage_${key}`))
        : key;
    },
    evidenceSummary(row: VisualRow): string {
      const parts: string[] = [];
      if (row.holds !== undefined && row.support !== undefined) {
        parts.push(
          String(
            this.$t('validation_assistant_visual_cases_match', {
              matches: row.holds,
              total: row.support,
            }),
          ),
        );
      } else {
        for (const key of ['holds', 'support'] as const) {
          if (row[key] !== undefined)
            parts.push(
              `${row[key]} ${this.$t(`validation_assistant_visual_${key}`)}`,
            );
        }
      }
      if (row.exceptions !== undefined)
        parts.push(
          String(
            this.$t(
              'validation_assistant_visual_exception_count',
              { count: row.exceptions },
              row.exceptions,
            ),
          ),
        );
      if (row.window_days !== undefined)
        parts.push(
          String(
            this.$t(
              'validation_assistant_visual_day_count',
              { count: row.window_days },
              row.window_days,
            ),
          ),
        );
      if (row.corrections !== undefined)
        parts.push(
          `${row.corrections} ${this.$t('validation_assistant_visual_corrections')}`,
        );
      return parts.join(', ');
    },
    evidenceMeter(row: VisualRow): boolean[] {
      const total = row.support ?? (row.holds ?? 0) + (row.exceptions ?? 0);
      const count = Math.min(30, Math.ceil(total));
      if (!count) return [];
      const exceptions = Math.min(
        total,
        row.exceptions ?? Math.max(0, total - (row.holds ?? total)),
      );
      const exceptional =
        exceptions === 0
          ? 0
          : exceptions === total
            ? count
            : Math.max(
                1,
                Math.min(count - 1, Math.round((count * exceptions) / total)),
              );
      return Array.from(
        { length: count },
        (_, index) => index >= count - exceptional,
      );
    },
  },
});
</script>

