import { computed, nextTick, onBeforeUnmount, ref, watch, type Ref } from 'vue';
import {
  sceneIndexAt,
  type Explainer,
} from 'src/utils/validationAssistant/explainer';
import {
  validationAssistantExplainerService as service,
  ExplainerAudioError,
} from 'src/services/validationAssistant/validationAssistantExplainerService';
import { useSettingStore } from 'src/store/main';
import { validation_explainer_audio_enabled_setting } from 'src/constants';
import { isExplainerAudioEnabled } from 'src/utils/validationAssistant/explainerAudioPreference';

export const AUDIO_POLL_MS = 1000;
export const AUDIO_POLL_MAX_MS = 30000;
const REASONS: Record<string, string> = {
  language: 'validation_assistant_explainer_audio_reason_language',
  disabled: 'validation_assistant_explainer_audio_reason_disabled',
  quota: 'validation_assistant_explainer_audio_reason_quota',
};
const abortError = () => new DOMException('aborted', 'AbortError');

/** Same token/poll/blob protocol as the former player; no silent animation timeline. */
export function useExplainerNarration(explainer: Ref<Explainer>) {
  const settings = useSettingStore();
  const audio = ref<HTMLAudioElement>();
  const audioUrl = ref('');
  const phase = ref<'idle' | 'loading' | 'playing'>('idle');
  const sceneIndex = ref(-1);
  const notice = ref('');
  let starts: number[] = [];
  let gen = 0;
  let ctrl: AbortController | null = null;
  let deadline: ReturnType<typeof setTimeout> | null = null;
  const enabled = computed(() =>
    isExplainerAudioEnabled(
      settings?.org_based_settings?.[
        validation_explainer_audio_enabled_setting
      ],
    ),
  );
  const available = computed(
    () => explainer.value.audio.available && enabled.value,
  );
  const reason = computed(() =>
    !enabled.value
      ? REASONS.disabled
      : explainer.value.audio.available === false
        ? (REASONS[explainer.value.audio.reason ?? ''] ?? '')
        : '',
  );
  const currentScene = computed(() =>
    phase.value === 'playing'
      ? explainer.value.scenes[sceneIndex.value]
      : undefined,
  );
  function clearDeadline() {
    if (deadline) clearTimeout(deadline);
    deadline = null;
  }
  function stop() {
    gen += 1;
    ctrl?.abort();
    ctrl = null;
    clearDeadline();
    phase.value = 'idle';
    sceneIndex.value = -1;
    try {
      audio.value?.pause();
      if (audio.value) audio.value.currentTime = 0;
    } catch {
      /* Detached media may refuse. */
    }
  }
  function release() {
    stop();
    if (audioUrl.value) URL.revokeObjectURL(audioUrl.value);
    audioUrl.value = '';
    starts = [];
  }
  function detach<T>(work: Promise<T>, signal: AbortSignal): Promise<T> {
    return new Promise((resolve, reject) => {
      if (signal.aborted) return reject(abortError());
      const onAbort = () => reject(abortError());
      signal.addEventListener('abort', onAbort, { once: true });
      work.then(
        (value) => {
          signal.removeEventListener('abort', onAbort);
          resolve(value);
        },
        (err) => {
          signal.removeEventListener('abort', onAbort);
          reject(err);
        },
      );
    });
  }
  function sleep(signal: AbortSignal): Promise<void> {
    return new Promise((resolve, reject) => {
      if (signal.aborted) return reject(abortError());
      const timer = setTimeout(() => {
        signal.removeEventListener('abort', onAbort);
        resolve();
      }, AUDIO_POLL_MS);
      const onAbort = () => {
        clearTimeout(timer);
        reject(abortError());
      };
      signal.addEventListener('abort', onAbort, { once: true });
    });
  }
  async function playAudio(generation: number) {
    const el = audio.value;
    if (!el) {
      stop();
      return;
    }
    el.currentTime = 0;
    try {
      await el.play();
      if (generation !== gen) {
        el.pause();
        return;
      }
      phase.value = 'playing';
      sceneIndex.value = 0;
    } catch {
      if (generation !== gen) return;
      stop();
      notice.value = 'validation_assistant_explainer_audio_blocked';
    }
  }
  async function play() {
    if (
      phase.value !== 'idle' ||
      !available.value ||
      !explainer.value.audio.available
    )
      return;
    const token = explainer.value.audio.token;
    stop();
    const generation = gen;
    notice.value = '';
    phase.value = 'loading';
    if (audioUrl.value) {
      await playAudio(generation);
      return;
    }
    const controller = new AbortController();
    ctrl = controller;
    let timedOut = false;
    deadline = setTimeout(() => {
      timedOut = true;
      controller.abort();
    }, AUDIO_POLL_MAX_MS);
    try {
      let timing = await detach(
        service.requestAudio(token, controller.signal),
        controller.signal,
      );
      while (timing.status === 'pending') {
        await sleep(controller.signal);
        timing = await detach(
          service.requestAudio(token, controller.signal),
          controller.signal,
        );
      }
      if (timing.status !== 'ready' || !timing.audio_id)
        throw new ExplainerAudioError(timing.status);
      const nextStarts = timing.scene_starts ?? [];
      if (nextStarts.length !== explainer.value.scenes.length)
        throw new ExplainerAudioError('scene_starts mismatch');
      const blob = await detach(
        service.fetchAudioBlob(timing.audio_id, controller.signal),
        controller.signal,
      );
      if (generation !== gen) return;
      clearDeadline();
      starts = nextStarts;
      audioUrl.value = URL.createObjectURL(blob);
      await nextTick();
      if (generation === gen) await playAudio(generation);
    } catch (err) {
      if (generation !== gen) return;
      if (
        !timedOut &&
        (controller.signal.aborted || (err as Error)?.name === 'AbortError')
      )
        return;
      stop();
      notice.value = 'validation_assistant_explainer_audio_unavailable';
    } finally {
      if (ctrl === controller) {
        ctrl = null;
        clearDeadline();
      }
    }
  }
  function onTimeUpdate() {
    if (phase.value !== 'playing' || !audio.value) return;
    sceneIndex.value = Math.min(
      sceneIndexAt(starts, audio.value.currentTime),
      explainer.value.scenes.length - 1,
    );
  }
  function onAudioError() {
    release();
    notice.value = 'validation_assistant_explainer_audio_unavailable';
  }
  watch(explainer, () => {
    release();
    notice.value = '';
  });
  watch(available, (value) => {
    if (!value) release();
  });
  onBeforeUnmount(release);
  return {
    audio,
    audioUrl,
    phase,
    currentScene,
    notice,
    reason,
    available,
    play,
    stop,
    onTimeUpdate,
    onAudioError,
  };
}
