import { toBoolPreference } from 'src/utils/preferenceBool';

/**
 * CORE-6235: VALIDATION_EXPLAINER_AUDIO_ENABLED defaults to ON — only an
 * explicitly falsy value ('false', '0', ...) switches the voice-over off.
 */
export function isExplainerAudioEnabled(raw: unknown): boolean {
  if (raw === undefined || raw === null || raw === '') return true;
  return toBoolPreference(raw);
}
