  >
    <!-- CORE-6161: collapsed by default in the panel -- video icon, title and the preview chips -->
    <template v-if="collapsible" #header>
      <button
        type="button"
        class="expl-card__toggle"
        :aria-expanded="expanded ? 'true' : 'false'"
        data-test="validation-assistant-explainer-toggle"
        @click="expanded = !expanded"
      >
        <Icon icon="mdi:play-circle-outline" width="18" height="18" class="expl-card__toggle-icon" />
        <span class="expl-card__toggle-title">{{ explainer.title }}</span>
        <Icon
          :icon="expanded ? 'mdi:chevron-up' : 'mdi:chevron-down'"
          width="18"
          height="18"
          class="expl-card__toggle-chevron"
        />
      </button>
    </template>
    <div
      class="expl-card__badges"
      data-test="validation-assistant-explainer-card-badges"
    >
      <!-- CORE-6249: what the system recommends for this blocker; while it still checks, no recommendation -->
      <span
        v-if="explainer.pending"
        class="expl-card__badge expl-card__badge--pending"
        data-test="validation-assistant-explainer-card-pending"
      >
        {{ $t('validation_assistant_decision_pending') }}
      </span>
      <span
        v-else-if="decisionLabel"
