        {{ decisionLabel }}
      </span>
      <span
        v-if="explainer.field_label"
        class="expl-card__made-for"
        data-test="validation-assistant-explainer-card-made-for"
      >
        {{ $t('validation_assistant_explainer_made_for') }}
        <strong>{{ explainer.field_label }}</strong>
      </span>
    </div>

    <template v-if="isOpen">
    <ExplainerImage v-if="visual" :explainer="explainer" :visual="visual" />
    <template v-else>
      <ExplainerDiagram
        :active-stage="explainer.diagram.active_stage"
        :example="explainer.diagram.example"
