      <p
        v-if="leadSentence"
        class="expl-card__lead"
        data-test="validation-assistant-explainer-lead"
      >
        {{ leadSentence }}
      </p>
    </template>

    <template v-if="!visual">
      <ul
        v-if="evidenceChips.length"
        class="expl-card__chips"
        data-test="validation-assistant-explainer-evidence"
      >
        <li
          v-for="chip in evidenceChips"
          :key="chip"
          class="expl-card__chip"
          data-test="validation-assistant-explainer-chip"
        >
          {{ chip }}
        </li>
      </ul>

      <div
        v-if="impact"
        class="expl-card__impact"
        data-test="validation-assistant-explainer-impact"
      >
        <p class="expl-card__impact-label">
          <Icon
            icon="mdi:chart-line"
            width="14"
            height="14"
            aria-hidden="true"
          />
          {{ $t('validation_assistant_explainer_section_impact') }}
        </p>
        <p
          class="expl-card__impact-headline"
          data-test="validation-assistant-explainer-impact-headline"
        >
          {{
            $t('validation_assistant_explainer_impact_headline', {
              current: ratePercent(impact.current_rate),
              potential: ratePercent(impact.potential_rate),
              delta: deltaPpText(impact),
            })
          }}
        </p>
        <p
          class="expl-card__impact-detail"
          data-test="validation-assistant-explainer-impact-detail"
        >
          {{ impactDetail }}
        </p>
      </div>

      <dl
        class="expl-card__sections"
        data-test="validation-assistant-explainer-sections"
      >
        <div
          v-for="(section, index) in visibleSections"
          :key="`${section.kind}-${index}`"
          class="expl-card__section"
          :class="`expl-card__section--${section.kind}`"
          :data-kind="section.kind"
          data-test="validation-assistant-explainer-section"
        >
          <dt class="expl-card__label">
            <Icon
              :icon="SECTION_ICONS[section.kind]"
              width="14"
              height="14"
              aria-hidden="true"
            />
            {{ $t(`validation_assistant_explainer_section_${section.kind}`) }}
          </dt>
          <dd class="expl-card__text">{{ section.text }}</dd>
        </div>
      </dl>
    </template>

    <ul
      v-if="missingEvidenceLabels.length"
      class="expl-card__chips"
      data-test="validation-assistant-explainer-missing-evidence"
    >
      <li class="expl-card__chip expl-card__chip--label">
        {{ $t('validation_assistant_decision_missing_evidence') }}
      </li>
      <li
        v-for="item in missingEvidenceLabels"
        :key="item"
        class="expl-card__chip"
        data-test="validation-assistant-explainer-missing-evidence-item"
      >
        {{ item }}
      </li>
    </ul>

    <!-- CORE-6249: the three effects, each with its result and how it is known; unknown is never zero -->
    <dl
      v-if="effectRows.length"
      class="expl-card__effects"
      data-test="validation-assistant-explainer-effects"
    >
      <div
        v-for="row in effectRows"
        :key="row.axis"
        class="expl-card__effect"
        :class="`expl-card__effect--${row.result}`"
        :data-axis="row.axis"
        :data-result="row.result"
        :data-basis="row.basis"
        data-test="validation-assistant-explainer-effect"
      >
        <dt class="expl-card__effect-label">{{ row.label }}</dt>
        <dd class="expl-card__effect-value">{{ row.text }}</dd>
      </div>
    </dl>

    <p
      v-if="explainer.more"
      class="expl-card__more"
      data-test="validation-assistant-explainer-more"
    >
      {{ explainer.more.text }}
    </p>
    </template>

    <template v-if="isOpen" #actions>
      <q-btn
        v-if="formAction"
        unelevated
        no-caps
        dense
        color="primary"
        class="expl-card__btn"
        icon="edit_note"
        :label="$t('validation_assistant_apply_to_document')"
        data-test="validation-assistant-explainer-apply-form"
        @click="$emit('apply-form', formAction)"
      />
      <template v-if="explainer.can_apply">
        <q-btn
          v-if="explainer.apply_ref"
          unelevated
          no-caps
          dense
          color="primary"
          class="expl-card__btn"
          :label="applyLabel"
          data-test="validation-assistant-explainer-apply"
          @click="$emit('apply', explainer.apply_ref)"
        />
      </template>
      <template v-else>
        <p
          v-if="explainer.decision && decisionActionLabel"
          class="expl-card__hint expl-card__hint--action"
          role="status"
          data-test="validation-assistant-explainer-decision-action"
        >
          {{ decisionActionLabel }}
        </p>
        <p
          v-else-if="!explainer.decision"
          class="expl-card__hint"
          data-test="validation-assistant-explainer-admin-hint"
        >
          {{ $t('validation_assistant_explainer_ask_admin') }}
        </p>
        <!-- CORE-6263: the primary way to ask an admin; the copy summary stays as the fallback -->
        <template v-if="canRequest">
          <span
            v-if="requestChip"
            class="expl-card__request-chip"
            :class="`expl-card__request-chip--${requestChip.kind}`"
            role="status"
            data-test="validation-assistant-explainer-request-status"
            :data-status="requestChip.kind"
          >
            {{ requestChip.text }}
          </span>
          <q-btn
            v-else
            unelevated
            no-caps
            dense
            color="primary"
            class="expl-card__btn"
            :loading="requesting"
            :disable="requesting"
            :label="$t('validation_assistant_improvement_suggest')"
            data-test="validation-assistant-explainer-suggest"
            @click="suggestImprovement"
          />
        </template>
        <q-btn
          :outline="!canRequest"
          :flat="canRequest"
          no-caps
          dense
          color="primary"
          class="expl-card__btn"
          :label="
            copied
              ? $t('validation_assistant_explainer_copied')
              : $t('validation_assistant_explainer_copy')
          "
          data-test="validation-assistant-explainer-copy"
          @click="copySummary"
        />
      </template>
    </template>
  </AssistantActionCard>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { Icon } from '@iconify/vue';
import AssistantActionCard from 'src/components/AssistantChat/AssistantActionCard.vue';
import ExplainerDiagram from 'src/components/ValidationAssistant/ExplainerDiagram.vue';
import ExplainerImage from 'src/components/ValidationAssistant/ExplainerImage.vue';
import { parseExplainerVisual } from 'src/utils/validationAssistant/explainerVisual';
import { notify } from 'src/components/notifications/notify';
import { validationAssistantImprovementService } from 'src/services/validationAssistant/validationAssistantImprovementService';
import type { DocumentRequestStatus } from 'src/utils/validationAssistant/improvementRequest';
import {
  deltaPpText,
  explainerSummaryText,
  ratePercent,
  type Explainer,
  type EffectAxisName,
  type ExplainerApplyRef,
  type ExplainerSectionKind,
  EFFECT_AXES,
} from 'src/utils/validationAssistant/explainer';
import type { AssistantAction } from 'src/utils/validationAssistantActions';

// only icons that are in the offline MDI bundle (src/icons/mdi-selective.json)
const SECTION_ICONS: Record<ExplainerSectionKind, string> = {
  problem: 'mdi:alert-circle-outline',
  where: 'mdi:text-box-outline',
  change: 'mdi:swap-horizontal',
  result: 'mdi:check-circle-outline',
  safety: 'mdi:shield-check-outline',
  impact: 'mdi:chart-line',
  decision: 'mdi:swap-horizontal',
  alternative: 'mdi:text-box-outline',
  options: 'mdi:swap-horizontal',
  blockers: 'mdi:alert-circle-outline',
  next_step: 'mdi:shield-check-outline',
};

export default defineComponent({
  name: 'ValidationAssistantExplainerCard',
  components: { AssistantActionCard, ExplainerDiagram, ExplainerImage, Icon },
  props: {
    explainer: { type: Object as PropType<Explainer>, required: true },
    /** CORE-6263: the document this card was shown for; without it no request can be filed. */
    docId: { type: String, default: '' },
    /** false on the dashboard, where the admin decides instead of asking. */
    allowRequest: { type: Boolean, default: true },
    /** Panel compatibility flag; explanations remain fully readable. */
    compact: { type: Boolean, default: false },
    /** CORE-6161: start closed as one line; each card opens on its own. */
    collapsible: { type: Boolean, default: false },
    /** CORE-6307: the viewer may change THIS document's form (editor, editable screen). */
    canApplyForm: { type: Boolean, default: false },
  },
  emits: {
    // the panel scrolls to and highlights the existing apply card; this card never applies
    apply: (_ref: ExplainerApplyRef) => true,
    // CORE-6307: the set_value card for this document's form; the panel runs it (undo included)
    'apply-form': (_action: AssistantAction) => true,
  },
  data() {
    return {
      SECTION_ICONS,
      ratePercent,
      deltaPpText,
      copied: false,
      expanded: false,
      copiedTimer: null as ReturnType<typeof setTimeout> | null,
      requesting: false,
      requestStatus: null as DocumentRequestStatus | null,
      requestedOn: null as string | null,
    };
  },
  computed: {
    isOpen(): boolean {
      return !this.collapsible || this.expanded;
    },
    visual() {
      return parseExplainerVisual(this.explainer.visual);
    },
    /** The one sentence under the image: the first scene's caption, else the problem. */
    leadSentence(): string {
      return (
        this.explainer.scenes[0]?.caption ||
        this.explainer.sections[0]?.text ||
        ''
      );
    },
    formAction(): AssistantAction | null {
      return this.canApplyForm ? this.explainer.form_action : null;
    },
    canRequest(): boolean {
      // Forward completed decisions for human review; no decision gets an Apply path.
      return (
        this.allowRequest &&
        !this.explainer.can_apply &&
        !this.explainer.pending &&
        !!this.docId
      );
    },
    /** "Use existing rule", "Other change (master data)", "Deferred (no history)" ... */
    decisionLabel(): string {
      const d = this.explainer.decision;
      if (!d) return '';
      if (d.operation === 'other_change' && d.other_change_kind) {
        return String(
          this.$t('validation_assistant_decision_op_other_change_kind', {
            kind: String(
              this.$t(
                `validation_assistant_decision_kind_${d.other_change_kind}`,
              ),
            ),
          }),
        );
      }
      if (d.operation === 'defer' && d.defer_reason) {
        return String(
          this.$t('validation_assistant_decision_op_defer_reason', {
            reason: String(
              this.$t(`validation_assistant_decision_defer_${d.defer_reason}`),
            ),
          }),
        );
      }
      return String(this.$t(`validation_assistant_decision_op_${d.operation}`));
    },
    isWritingOperation(): boolean {
      const op = this.explainer.decision?.operation;
      return (
        op === 'create_transformation' ||
        op === 'create_validation' ||
        op === 'update_existing'
      );
    },
    applyLabel(): string {
      return String(
        this.$t(
          this.isWritingOperation
            ? 'validation_assistant_decision_action_create_rule'
            : 'validation_assistant_explainer_apply',
        ),
      );
    },
    /** What the person does next: review a change, or collect more evidence. Null while pending. */
    decisionActionLabel(): string {
      const d = this.explainer.decision;
      if (!d || this.explainer.pending) return '';
      if (d.operation === 'defer') {
        return String(
          this.$t('validation_assistant_decision_action_more_evidence'),
        );
      }
      return String(
        this.$t('validation_assistant_decision_action_review_change'),
      );
    },
    /** The impact text of a decision is replaced by the effect rows below. */
    visibleSections() {
      const decisionCard = !!this.explainer.decision;
      return this.explainer.sections.filter(
        (section) => !(decisionCard && section.kind === 'impact'),
      );
    },
    missingEvidenceLabels(): string[] {
      const d = this.explainer.decision;
      if (!d || this.explainer.pending) return [];
      return d.missing_evidence.map((item) =>
        String(this.$t(`validation_assistant_decision_missing_${item}`)),
      );
    },
    effectRows(): {
      axis: EffectAxisName;
      label: string;
      text: string;
      result: string;
      basis: string;
    }[] {
      const effect = this.explainer.effect;
      // pending: no effect is claimed at all
      if (!effect || this.explainer.pending) return [];
      return EFFECT_AXES.map((axis) => {
        const { result, basis } = effect[axis];
        const resultText = String(
          this.$t(`validation_assistant_decision_result_${result}`),
        );
        // an unknown result has no meaningful basis; zero and negative are said as they are
        const text =
          result === 'unknown'
            ? resultText
            : String(
                this.$t('validation_assistant_decision_result_with_basis', {
                  result: resultText,
                  basis: String(
                    this.$t(`validation_assistant_decision_basis_${basis}`),
                  ),
                }),
              );
        return {
          axis,
          label: String(
            this.$t(`validation_assistant_decision_effect_${axis}`),
          ),
          text,
          result,
          basis,
        };
      });
    },
    /** "Requested on …" / "Implemented" / "Declined: <reason>"; null = nothing asked yet (or expired). */
    requestChip(): { kind: string; text: string } | null {
      const status = this.requestStatus;
      if (!status) return null;
      if (status.status === 'pending') {
        const date = this.formatDate(this.requestedOn || status.requested_on);
        return {
          kind: 'pending',
          text: String(
            date
              ? this.$t('validation_assistant_improvement_requested_on', {
                  date,
                })
              : this.$t('validation_assistant_improvement_requested'),
          ),
        };
      }
      if (status.status === 'approved') {
        return {
          kind: 'approved',
          text: String(this.$t('validation_assistant_improvement_implemented')),
        };
      }
      if (status.status === 'rejected') {
        const code = status.decision_reason_code;
        const reason =
          status.decision_note ||
          (code
            ? String(this.$t(`validation_assistant_improvement_reason_${code}`))
            : '');
        return {
          kind: 'rejected',
          text: String(
            reason
              ? this.$t('validation_assistant_improvement_declined', { reason })
              : this.$t('validation_assistant_improvement_declined_plain'),
          ),
        };
      }
      return null;
    },
    impact() {
      return this.explainer.touchless_impact;
    },
    impactDetail(): string {
      const impact = this.explainer.touchless_impact;
      if (!impact) return '';
      return String(
        this.$t(
          impact.window_days
            ? 'validation_assistant_explainer_impact_detail'
            : 'validation_assistant_explainer_impact_detail_nowindow',
          {
            gained: impact.documents_gained.toLocaleString(),
            total: impact.total_documents.toLocaleString(),
            days: impact.window_days,
          },
        ),
      );
    },
    evidenceChips(): string[] {
      const ev = this.explainer.evidence;
      if (!ev) return [];
      const chips: string[] = [];
      if (ev.source === 'document') {
        chips.push(
          String(this.$t('validation_assistant_explainer_evidence_document')),
        );
        return chips;
      }
      if (ev.corrections) {
        // "<n> corrections in <m> documents · last 60 days"
        const docs = ev.documents_with_correction;
        const days = ev.window_days;
        const key =
          docs && days
            ? 'validation_assistant_explainer_evidence_corrections'
            : docs
              ? 'validation_assistant_explainer_evidence_corrections_nowindow'
              : 'validation_assistant_explainer_evidence_corrections_only';
        chips.push(
          String(
            this.$t(key, {
              corrections: ev.corrections,
              documents: docs,
              days,
            }),
          ),
        );
      }
      return chips;
    },
  },
  mounted() {
    if (this.canRequest) void this.loadRequestStatus();
  },
  beforeUnmount() {
    if (this.copiedTimer) clearTimeout(this.copiedTimer);
  },
  methods: {
    formatDate(iso: string | null): string {
      if (!iso) return '';
      const parsed = new Date(iso);
      return Number.isNaN(parsed.getTime()) ? '' : parsed.toLocaleDateString();
    },
    async loadRequestStatus() {
      try {
        const items = await validationAssistantImprovementService.byDocument(
          this.docId,
        );
        this.requestStatus =
          items.find((item) => item.offer_id === this.explainer.offer_id) ??
          null;
      } catch {
        // the chip is a convenience; without it the button still works
        this.requestStatus = null;
      }
    },
    async suggestImprovement() {
      if (this.requesting) return;
      this.requesting = true;
      try {
        const { request, created } =
          await validationAssistantImprovementService.create(
            this.docId,
            this.explainer.offer_id,
          );
        this.requestedOn = request.created_on;
        this.requestStatus = {
          offer_id: this.explainer.offer_id,
          request_id: request.id,
          status: request.status,
          requested_on: request.created_on,
          decided_on: request.decided_on,
          decision_reason_code: request.decision_reason_code,
          decision_note: request.decision_note,
        };
        if (created) {
          notify.success(
            String(this.$t('validation_assistant_improvement_created')),
          );
        } else {
          // somebody asked before: this click only raised the count
          notify.info(
            String(
              this.$t('validation_assistant_improvement_deduped', {
                count: request.request_count,
              }),
            ),
          );
        }
      } catch (error) {
        const status = (error as { status?: number })?.status;
        notify.error(
          String(
            this.$t(
              status === 429
                ? 'validation_assistant_improvement_rate_limited'
                : 'validation_assistant_improvement_failed',
            ),
          ),
        );
      } finally {
        this.requesting = false;
      }
    },
    async copySummary() {
      try {
        await navigator.clipboard.writeText(
          explainerSummaryText(this.explainer),
        );
      } catch {
        return;
      }
      this.copied = true;
      if (this.copiedTimer) clearTimeout(this.copiedTimer);
      this.copiedTimer = setTimeout(() => {
        this.copied = false;
      }, 2000);
    },
  },
});
</script>

