/**
 * CORE-6258 — client for the improvement requests (doc2-api
 * `/v3/validation-assistant/improvements/...`, contract in CORE-6258).
 *
 * Same raw `fetch` + auth headers as the explainer audio client: the contract
 * has no generated SDK yet, and the error body (`{ error_code }`) matters here.
 */
import { getAuthorizationToken } from 'src/pages/APIs';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { OpenAPI } from 'src/generated-api-sdk/core/OpenAPI';
import {
  parseDocumentStatuses,
  parseRequest,
  parseRequests,
  type DocumentRequestStatus,
  type ImprovementRequest,
  type ImprovementStatus,
  type RejectReason,
} from 'src/utils/validationAssistant/improvementRequest';

export const IMPROVEMENTS_PATH = '/v3/validation-assistant/improvements';

/** Safety cap of `listAll`: 50 pages of 100. */
export const LIST_ALL_MAX_PAGES = 50;

export class ImprovementRequestError extends Error {
  status: number;
  code: string;
  constructor(message: string, status = 0, code = '') {
    super(message);
    this.name = 'ImprovementRequestError';
    this.status = status;
    this.code = code;
  }
}

async function authHeaders(): Promise<Record<string, string>> {
  const token = await getAuthorizationToken();
  const orgId = getOrgId();
  return {
    Authorization: token || '',
    ...(orgId ? { 'X-ORG-ID': orgId } : {}),
  };
}

async function call(
  method: 'GET' | 'POST',
  path: string,
  body?: unknown,
  signal?: AbortSignal,
): Promise<unknown> {
  const response = await fetch(`${OpenAPI.BASE}${IMPROVEMENTS_PATH}${path}`, {
    method,
    headers: {
      ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}),
      ...(await authHeaders()),
    },
    body: body !== undefined ? JSON.stringify(body) : undefined,
    signal,
  });
  let payload: unknown = null;
  try {
    payload = await response.json();
  } catch {
    payload = null;
  }
  if (!response.ok) {
    const err = (payload ?? {}) as {
      error_code?: unknown;
      detail?: unknown;
      message?: unknown;
    };
    const code = String(err.error_code ?? '');
    throw new ImprovementRequestError(
      typeof err.message === 'string' ? err.message : `HTTP ${response.status}`,
      response.status,
      code,
    );
  }
  return payload;
}

export interface CreateResult {
  request: ImprovementRequest;
  /** false: somebody had already suggested it; the count went up instead. */
  created: boolean;
}

export interface ListParams {
  status?: ImprovementStatus;
  docType?: string;
  limit?: number;
  offset?: number;
}

export const validationAssistantImprovementService = {
  async create(docId: string, offerId: string): Promise<CreateResult> {
    const body = (await call('POST', '/requests', {
      doc_id: docId,
      offer_id: offerId,
    })) as { request?: unknown; created?: unknown };
    const request = parseRequest(body?.request);
    if (!request) throw new ImprovementRequestError('bad response');
    return { request, created: body.created !== false };
  },

  async list(
    params: ListParams = {},
    signal?: AbortSignal,
  ): Promise<{ items: ImprovementRequest[]; total: number }> {
    const q = new URLSearchParams();
    if (params.status) q.set('status', params.status);
    if (params.docType) q.set('doc_type', params.docType);
    q.set('limit', String(params.limit ?? 50));
    q.set('offset', String(params.offset ?? 0));
    const body = (await call('GET', `/requests?${q.toString()}`, undefined, signal)) as {
      items?: unknown;
      total?: unknown;
    };
    const items = parseRequests(body?.items);
    return {
      items,
      total: typeof body?.total === 'number' ? body.total : items.length,
    };
  },

  /**
   * The requests of a status from `offset` on: pages are read until `total` is
   * reached (the server caps a page at 100) or `maxPages` is used up. The cap is
   * a safety net, never a silent cut: the caller compares `total` with what it
   * holds and offers to continue from its own offset.
   */
  async listAll(
    params: Omit<ListParams, 'limit'> & { maxPages?: number } = {},
    signal?: AbortSignal,
  ): Promise<{ items: ImprovementRequest[]; total: number }> {
    const pageSize = 100;
    const maxPages = params.maxPages ?? LIST_ALL_MAX_PAGES;
    const start = params.offset ?? 0;
    const items: ImprovementRequest[] = [];
    let total = 0;
    for (let page = 0; page < maxPages; page += 1) {
      const offset = start + page * pageSize;
      const result = await this.list(
        { status: params.status, docType: params.docType, limit: pageSize, offset },
        signal,
      );
      total = result.total;
      items.push(...result.items);
      if (!result.items.length || offset + pageSize >= total) break;
    }
    return { items, total };
  },

  async get(id: string, signal?: AbortSignal): Promise<ImprovementRequest> {
    const body = await call(
      'GET',
      `/requests/${encodeURIComponent(id)}`,
      undefined,
      signal,
    );
    const request = parseRequest(body);
    if (!request) throw new ImprovementRequestError('bad response');
    return request;
  },

  async byDocument(docId: string, signal?: AbortSignal): Promise<DocumentRequestStatus[]> {
    const body = (await call(
      'GET',
      `/requests/by-document/${encodeURIComponent(docId)}`,
      undefined,
      signal,
    )) as { items?: unknown };
    return parseDocumentStatuses(body?.items);
  },

  async approve(id: string, activate: boolean): Promise<ImprovementRequest> {
    const body = await call('POST', `/requests/${encodeURIComponent(id)}/approve`, {
      activate,
    });
    const request = parseRequest(body);
    if (!request) throw new ImprovementRequestError('bad response');
    return request;
  },

  async reject(
    id: string,
    reasonCode: RejectReason,
    note: string,
  ): Promise<ImprovementRequest> {
    const body = await call('POST', `/requests/${encodeURIComponent(id)}/reject`, {
      reason_code: reasonCode,
      note: note.trim(),
    });
    const request = parseRequest(body);
    if (!request) throw new ImprovementRequestError('bad response');
    return request;
  },

  /** Voice-over token for the request's explainer; null when none is available. */
  async audioToken(id: string): Promise<string | null> {
    const body = (await call(
      'POST',
      `/requests/${encodeURIComponent(id)}/audio-token`,
      {},
    )) as { token?: unknown };
    return typeof body?.token === 'string' && body.token ? body.token : null;
  },
};

export default validationAssistantImprovementService;
