/** Static, fully readable projection of an explainer. Unknown versions fall back to v1 cards. */
export const VISUAL_TEMPLATES = [
  'explain_rule',
  'explain_problem',
  'flowchart',
  'decision_table',
  'plain',
] as const;
export type VisualTemplate = (typeof VISUAL_TEMPLATES)[number];
export interface VisualStage {
  key: string;
  state: 'done' | 'failed' | 'pending';
}
export interface VisualRow {
  id: string;
  kind: string;
  scene: string | null;
  text?: string;
  before?: string;
  after?: string;
  expected?: string;
  actual?: string;
  corrections?: number;
  holds?: number;
  support?: number;
  exceptions?: number;
  window_days?: number;
  stages?: VisualStage[];
  fail?: { text: string };
}
export interface ExplainerImageData {
  version: 1;
  template: VisualTemplate;
  rows: VisualRow[];
}
const SHARED_KINDS = ['change', 'impact', 'result', 'safety', 'remaining'];
const KINDS: Record<VisualTemplate, string[]> = {
  explain_rule: ['purpose', 'condition', 'then', 'evidence', 'example'],
  explain_problem: ['problem', 'expected_actual', 'evidence', 'next_step'],
  flowchart: ['flow', 'reason', 'next_step'],
  decision_table: ['problem', 'check', 'outcome', 'next_step'],
  plain: ['what_happened', 'what_it_means', 'what_next'],
};
export function parseExplainerVisual(
  value: unknown,
): ExplainerImageData | null {
  if (!value || typeof value !== 'object') return null;
  const v = value as ExplainerImageData;
  if (
    v.version !== 1 ||
    !VISUAL_TEMPLATES.includes(v.template) ||
    !Array.isArray(v.rows) ||
    !v.rows.length
  )
    return null;
  const ids = new Set<string>();
  for (const row of v.rows) {
    if (
      !row ||
      typeof row.id !== 'string' ||
      !row.id ||
      ids.has(row.id) ||
      (!KINDS[v.template].includes(row.kind) &&
        !SHARED_KINDS.includes(row.kind))
    )
      return null;
    ids.add(row.id);
    if (row.scene !== null && typeof row.scene !== 'string') return null;
    if (row.kind === 'flow') {
      if (
        !Array.isArray(row.stages) ||
        !row.stages.length ||
        row.stages.some(
          (s) =>
            !s ||
            typeof s.key !== 'string' ||
            !['done', 'failed', 'pending'].includes(s.state),
        )
      )
        return null;
    } else if (row.kind === 'outcome') {
      if (!row.fail || typeof row.fail.text !== 'string') return null;
    } else if (row.kind === 'example') {
      if (typeof row.before !== 'string' || typeof row.after !== 'string')
        return null;
    } else if (row.kind === 'expected_actual') {
      if (typeof row.expected !== 'string' || typeof row.actual !== 'string')
        return null;
    } else if (row.kind === 'evidence' && v.template === 'explain_rule') {
      if (
        ['corrections', 'holds', 'support', 'exceptions', 'window_days'].some(
          (key) => {
            const n = row[key as keyof VisualRow];
            return (
              n !== undefined &&
              (typeof n !== 'number' || !Number.isFinite(n) || n < 0)
            );
          },
        )
      )
        return null;
    } else if (typeof row.text !== 'string') return null;
  }
  return v;
}
