<!-- CORE-6250: the pipeline an explainer talks about; the stage the change lives in is lit. -->
<template>
  <figure
    class="expl-diagram"
    :class="[`expl-diagram--${variant}`, { 'expl-diagram--animate': animate }]"
    data-test="validation-assistant-explainer-diagram"
    :data-active-stage="activeStage"
  >
    <svg
      class="expl-diagram__svg"
      viewBox="0 0 500 64"
      role="img"
      :aria-label="ariaLabel"
      preserveAspectRatio="xMidYMid meet"
    >
      <defs>
        <filter :id="glowId" x="-40%" y="-60%" width="180%" height="220%">
          <feGaussianBlur stdDeviation="4" result="blur" />
          <feMerge>
            <feMergeNode in="blur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>

      <g v-for="(stage, index) in stages" :key="stage">
        <path
          v-if="index < stages.length - 1"
          class="expl-diagram__link"
          :class="{ 'expl-diagram__link--on': index < activeIndex }"
          :d="linkPath(index)"
          pathLength="1"
          fill="none"
          data-test="validation-assistant-explainer-link"
          :style="{ '--expl-delay': `${index * 0.35}s` }"
        />
        <g
          class="expl-diagram__node"
          :class="{
            'expl-diagram__node--active': stage === activeStage,
            'expl-diagram__node--past': index < activeIndex,
          }"
          :data-stage="stage"
          :data-active="stage === activeStage ? 'true' : 'false'"
          data-test="validation-assistant-explainer-stage"
        >
          <rect
            class="expl-diagram__box"
            :x="nodeX(index)"
            y="14"
            :width="NODE_W"
            height="36"
            rx="9"
            :filter="stage === activeStage && glow ? `url(#${glowId})` : undefined"
          />
          <text
            class="expl-diagram__label"
            :x="nodeX(index) + NODE_W / 2"
            y="36"
            text-anchor="middle"
          >
            {{ stageLabel(stage) }}
          </text>
        </g>
      </g>
    </svg>

    <figcaption
      v-if="showCaption"
      class="expl-diagram__caption"
      data-test="validation-assistant-explainer-diagram-caption"
    >
      {{ $t('validation_assistant_explainer_diagram_simplified') }}
    </figcaption>

    <div
      v-if="showExample && example"
      class="expl-diagram__example"
      data-test="validation-assistant-explainer-example"
    >
      <span class="expl-diagram__example-label">{{
        $t('validation_assistant_explainer_example_label')
      }}</span>
      <span class="expl-diagram__value expl-diagram__value--before">{{
        example.before
      }}</span>
      <Icon
        icon="mdi:arrow-right"
        width="14"
        height="14"
        class="expl-diagram__example-arrow"
        aria-hidden="true"
      />
      <span class="expl-diagram__value expl-diagram__value--after">{{
        example.after
      }}</span>
    </div>
  </figure>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { Icon } from '@iconify/vue';
import {
  EXPLAINER_STAGES,
  type ExplainerExample,
  type ExplainerStage,
} from 'src/utils/validationAssistant/explainer';

const NODE_W = 84;
const GAP = 20;
let uid = 0;

export default defineComponent({
  name: 'ExplainerDiagram',
  components: { Icon },
  props: {
    activeStage: {
      type: String as PropType<ExplainerStage>,
      required: true,
    },
    example: {
      type: Object as PropType<ExplainerExample | null>,
      default: null,
    },
    showExample: { type: Boolean, default: true },
    // the diagram is conceptual: say so
    showCaption: { type: Boolean, default: true },
    // 'canvas' = the dark stage of the player
    variant: {
      type: String as PropType<'card' | 'canvas'>,
      default: 'card',
    },
    // arrows draw on instead of being there
    animate: { type: Boolean, default: false },
    glow: { type: Boolean, default: true },
  },
  data() {
    uid += 1;
    return { glowId: `expl-glow-${uid}`, NODE_W };
  },
  computed: {
    stages(): readonly ExplainerStage[] {
      return EXPLAINER_STAGES;
    },
    activeIndex(): number {
      return Math.max(0, this.stages.indexOf(this.activeStage));
    },
    ariaLabel(): string {
      return String(
        this.$t('validation_assistant_explainer_diagram_label', {
          stage: this.stageLabel(this.activeStage),
        }),
      );
    },
  },
  methods: {
    nodeX(index: number): number {
      return index * (NODE_W + GAP);
    },
    linkPath(index: number): string {
      const x = this.nodeX(index) + NODE_W + 2;
      return `M ${x} 32 L ${x + GAP - 6} 32 M ${x + GAP - 11} 27 L ${x + GAP - 5} 32 L ${x + GAP - 11} 37`;
    },
    stageLabel(stage: ExplainerStage): string {
      return String(this.$t(`validation_assistant_explainer_stage_${stage}`));
    },
  },
});
</script>

