/**
 * CORE-6235 — the `explainer` chunk of the Validation Assistant stream
 * (contract v1, doc2-api): one card per offer that explains WHAT the change
 * does, WHERE in the pipeline, and WHAT the user gets. Everything in it is
 * plain text; it is rendered as text nodes only, never as HTML.
 *
 * A payload is only rendered when it carries what the card needs. Anything
 * else is dropped, never half-drawn.
 */
import {
  normalizeAssistantAction,
  type AssistantAction,
} from 'src/utils/validationAssistantActions';

import { parseExplainerVisual, type ExplainerImageData } from './explainerVisual';

export const EXPLAINER_STAGES = [
  'extraction',
  'transformation',
  'lookup',
  'validation',
  'export',
] as const;
export type ExplainerStage = (typeof EXPLAINER_STAGES)[number];

export const EXPLAINER_SECTION_KINDS = [
  'problem',
  'where',
  'change',
  'result',
  'safety',
  'impact',
  // CORE-6249 (schema_version 2, blocker decisions)
  'decision',
  'alternative',
  'options',
  'blockers',
  'next_step',
] as const;
export type ExplainerSectionKind = (typeof EXPLAINER_SECTION_KINDS)[number];

export type ExplainerVisual =
  | 'value_in'
  | 'morph'
  | 'match'
  | 'search'
  | 'check'
  | 'touchless_gain'
  | 'flag'
  | 'arrow'
  | 'summary';
const VISUALS: ExplainerVisual[] = [
  'value_in',
  'morph',
  'match',
  'search',
  'check',
  'touchless_gain',
  'flag',
  'arrow',
  'summary',
];

export interface ExplainerSection {
  kind: ExplainerSectionKind;
  text: string;
}

export interface ExplainerExample {
  before: string;
  after: string;
}

export interface ExplainerDiagramData {
  stages: ExplainerStage[];
  active_stage: ExplainerStage;
  example: ExplainerExample | null;
}

export interface ExplainerEvidence {
  source: 'corrections' | 'document';
  corrections?: number;
  documents_with_correction?: number;
  window_days?: number;
  sample_cap?: number;
}

/** Estimate of the touchless rate with this change (upper bound, never a promise). */
export interface TouchlessImpact {
  current_rate: number;
  potential_rate: number;
  delta_pp: number;
  documents_gained: number;
  total_documents: number;
  window_days?: number;
  basis: string;
}

export interface ExplainerScene {
  id: string;
  stage: ExplainerStage;
  visual: ExplainerVisual;
  caption: string;
}

export type ExplainerAudio =
  | { available: true; token: string }
  | { available: false; reason?: string };

export interface ExplainerApplyRef {
  type: 'rule_preview' | 'settings_actions';
  id: string;
}

/** CORE-6249: explainer schema 2 -- one decision per blocker (doc2-api CORE-6238). */
export const BLOCKER_DECISION_KIND = 'blocker_decision';

export const DECISION_OPERATIONS = [
  'reuse',
  'repair_configuration',
  'update_existing',
  'create_transformation',
  'create_validation',
  'other_change',
  'defer',
] as const;
export type DecisionOperation = (typeof DECISION_OPERATIONS)[number];

export const OTHER_CHANGE_KINDS = [
  'master_data',
  'lookup_mapping',
  'extraction',
  'required_rule_review',
  'field_setting_review',
  'workflow',
] as const;
export type OtherChangeKind = (typeof OTHER_CHANGE_KINDS)[number];

export const DEFER_REASONS = [
  'no_history',
  'conflicting_history',
  'extraction_incomplete',
  'master_data_owner_needed',
  'context_incomplete',
  'target_state_unclear',
  'would_relax_required_check',
  'replay_unavailable',
] as const;
export type DeferReason = (typeof DEFER_REASONS)[number];

export const MISSING_EVIDENCE = [
  'history',
  'replay',
  'supplier_history',
  'master_data_coverage',
  'rule_context',
  'amount_components',
] as const;
export type MissingEvidence = (typeof MISSING_EVIDENCE)[number];

export const EFFECT_BASES = [
  'estimated',
  'replayed',
  'observed',
  'upper_bound',
] as const;
export type EffectBasis = (typeof EFFECT_BASES)[number];

export const EFFECT_RESULTS = ['positive', 'zero', 'negative', 'unknown'] as const;
export type EffectResult = (typeof EFFECT_RESULTS)[number];

export const EFFECT_AXES = ['corrections', 'touchless', 'quality'] as const;
export type EffectAxisName = (typeof EFFECT_AXES)[number];

export interface EffectAxis {
  basis: EffectBasis;
  result: EffectResult;
  value?: number;
  reason?: string;
}
export type ExplainerEffect = Record<EffectAxisName, EffectAxis>;

export interface DecisionAlternative {
  operation: string;
  reason_code: string;
  excluded: boolean;
}

export interface ExplainerDecision {
  operation: DecisionOperation;
  other_change_kind: OtherChangeKind | null;
  defer_reason: DeferReason | null;
  cause: string;
  evidence_level: string;
  next_step: string;
  /** how many OTHER blockers stay (a decision never claims to fix more than its own) */
  residual_blockers: number;
  alternatives: DecisionAlternative[];
  missing_evidence: MissingEvidence[];
  executable: boolean;
}

/** Operations that write a rule; only these may ever carry an apply reference. */
export const WRITING_OPERATIONS: readonly DecisionOperation[] = [
  'update_existing',
  'create_transformation',
  'create_validation',
];

export interface Explainer {
  schema_version: number;
  id: string;
  offer_id: string;
  offer_kind: string;
  field: string;
  field_label: string;
  finding_id: string;
  language: string;
  title: string;
  visual?: ExplainerImageData | null;
  sections: ExplainerSection[];
  diagram: ExplainerDiagramData;
  result_model: string;
  evidence: ExplainerEvidence | null;
  touchless_impact: TouchlessImpact | null;
  scenes: ExplainerScene[];
  audio: ExplainerAudio;
  can_apply: boolean;
  apply_ref: ExplainerApplyRef | null;
  /** v2: evidence still computing -- observed blocker, no recommendation */
  pending: boolean;
  /** v2 blocker decision; null for v1 explainers */
  decision: ExplainerDecision | null;
  /** v2: the three-axis effect; null for v1 explainers */
  effect: ExplainerEffect | null;
  /** v2: "N more blockers" summary of the last card */
  more: { count: number; text: string } | null;
  /** CORE-6307: impact (corrections x holds / support); the server orders by it */
  rank_score: number;
  /** CORE-6307: "apply to this document" -- a set_value card for the FORM only */
  form_action: AssistantAction | null;
}

/** CORE-6307: decisions that only defer, point elsewhere or are still checked
 * have no change the user could make here -- they collapse into one line. */
const NO_SAFE_CHANGE: readonly string[] = ['defer', 'other_change'];

export function hasSafeChange(explainer: Explainer): boolean {
  if (!isBlockerDecision(explainer)) return true;
  return (
    !explainer.pending && !NO_SAFE_CHANGE.includes(explainer.decision!.operation)
  );
}

function toFormAction(value: unknown): AssistantAction | null {
  const action = normalizeAssistantAction(value);
  return action && action.kind === 'set_value' ? action : null;
}

export function isBlockerDecision(explainer: Explainer): boolean {
  return explainer.offer_kind === BLOCKER_DECISION_KIND && !!explainer.decision;
}

/** Bases that prove a touchless gain; an estimate or upper bound never does. */
const PROVEN_BASES: readonly EffectBasis[] = ['replayed', 'observed'];

/**
 * The ONE predicate for the touchless-gain scene: a positive touchless effect,
 * proven by a replay or an observation, on a decision that is not pending.
 */
export function gainProven(
  effect: ExplainerEffect | null,
  pending: boolean,
): boolean {
  return (
    !pending &&
    effect?.touchless.result === 'positive' &&
    PROVEN_BASES.includes(effect.touchless.basis)
  );
}

export function touchlessGainProven(explainer: Explainer): boolean {
  return gainProven(explainer.effect, explainer.pending);
}

function str(value: unknown): string | null {
  return typeof value === 'string' && value.trim() ? value : null;
}

function isStage(value: unknown): value is ExplainerStage {
  return (EXPLAINER_STAGES as readonly unknown[]).includes(value);
}

function num(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isFinite(value)
    ? value
    : undefined;
}

function toSections(value: unknown): ExplainerSection[] {
  if (!Array.isArray(value)) return [];
  const out: ExplainerSection[] = [];
  for (const item of value) {
    const kind = (item as { kind?: unknown })?.kind;
    const text = str((item as { text?: unknown })?.text);
    if (
      text &&
      (EXPLAINER_SECTION_KINDS as readonly unknown[]).includes(kind)
    ) {
      out.push({ kind: kind as ExplainerSectionKind, text });
    }
  }
  return out;
}

function toDiagram(value: unknown): ExplainerDiagramData | null {
  const v = value as Record<string, unknown> | null;
  if (!v || typeof v !== 'object' || !isStage(v.active_stage)) return null;
  const ex = v.example as Record<string, unknown> | null | undefined;
  const before = str(ex?.before);
  const after = str(ex?.after);
  return {
    // the pipeline is fixed; never trust a reordered list
    stages: [...EXPLAINER_STAGES],
    active_stage: v.active_stage,
    example: before && after ? { before, after } : null,
  };
}

function toEvidence(value: unknown): ExplainerEvidence | null {
  const v = value as Record<string, unknown> | null;
  if (!v || typeof v !== 'object') return null;
  if (v.source !== 'corrections' && v.source !== 'document') return null;
  return {
    source: v.source,
    corrections: num(v.corrections),
    documents_with_correction: num(v.documents_with_correction),
    window_days: num(v.window_days),
    sample_cap: num(v.sample_cap),
  };
}

function toImpact(value: unknown): TouchlessImpact | null {
  const v = value as Record<string, unknown> | null;
  if (!v || typeof v !== 'object') return null;
  const current = num(v.current_rate);
  const potential = num(v.potential_rate);
  const gained = num(v.documents_gained);
  const total = num(v.total_documents);
  if (
    current === undefined ||
    potential === undefined ||
    gained === undefined ||
    total === undefined ||
    current < 0 ||
    current > 1 ||
    potential < current ||
    potential > 1
  ) {
    return null;
  }
  return {
    current_rate: current,
    potential_rate: potential,
    delta_pp: num(v.delta_pp) ?? Math.round((potential - current) * 1000) / 10,
    documents_gained: gained,
    total_documents: total,
    window_days: num(v.window_days),
    basis: str(v.basis) ?? 'upper_bound',
  };
}

/** Whole percent, as shown on screen. */
export function ratePercent(rate: number): number {
  return Math.round(rate * 100);
}

export function deltaPpText(impact: TouchlessImpact): string {
  const sign = impact.delta_pp >= 0 ? '+' : '';
  return `${sign}${impact.delta_pp.toLocaleString(undefined, {
    minimumFractionDigits: 1,
    maximumFractionDigits: 1,
  })} pp`;
}

function oneOf<T extends string>(list: readonly T[], value: unknown): T | null {
  return typeof value === 'string' && (list as readonly string[]).includes(value)
    ? (value as T)
    : null;
}

function toAxis(value: unknown): EffectAxis {
  const v = value as Record<string, unknown> | null;
  const result = v && typeof v === 'object' ? oneOf(EFFECT_RESULTS, v.result) : null;
  // an axis we cannot read is "unknown", never "zero"
  if (!result) return { basis: 'estimated', result: 'unknown' };
  const axis: EffectAxis = {
    basis: oneOf(EFFECT_BASES, v?.basis) ?? 'estimated',
    result,
  };
  const val = num(v?.value);
  if (val !== undefined && result === 'positive') axis.value = val;
  const reason = str(v?.reason);
  if (reason) axis.reason = reason;
  return axis;
}

function toEffect(value: unknown): ExplainerEffect {
  const v = (value && typeof value === 'object' ? value : {}) as Record<
    string,
    unknown
  >;
  return {
    corrections: toAxis(v.corrections),
    touchless: toAxis(v.touchless),
    quality: toAxis(v.quality),
  };
}

function toDecision(value: unknown): ExplainerDecision | null {
  const v = value as Record<string, unknown> | null;
  if (!v || typeof v !== 'object') return null;
  const operation = oneOf(DECISION_OPERATIONS, v.operation);
  if (!operation) return null;
  const residual = Array.isArray(v.residual_blockers)
    ? v.residual_blockers.length
    : (num(v.residual_blockers) ?? 0);
  const alternatives: DecisionAlternative[] = [];
  if (Array.isArray(v.alternatives)) {
    for (const item of v.alternatives) {
      const a = item as Record<string, unknown>;
      const op = str(a?.operation);
      const reason = str(a?.reason_code);
      if (op && reason) {
        alternatives.push({
          operation: op,
          reason_code: reason,
          excluded: a.excluded !== false,
        });
      }
    }
  }
  const missing: MissingEvidence[] = [];
  if (Array.isArray(v.missing_evidence)) {
    for (const item of v.missing_evidence) {
      const m = oneOf(MISSING_EVIDENCE, item);
      if (m && !missing.includes(m)) missing.push(m);
    }
  }
  return {
    operation,
    other_change_kind:
      operation === 'other_change' ? oneOf(OTHER_CHANGE_KINDS, v.other_change_kind) : null,
    defer_reason: operation === 'defer' ? oneOf(DEFER_REASONS, v.defer_reason) : null,
    cause: str(v.cause) ?? '',
    evidence_level: str(v.evidence_level) ?? '',
    next_step: str(v.next_step) ?? '',
    residual_blockers: Math.max(0, Math.floor(residual)),
    alternatives,
    missing_evidence: missing,
    executable: false,
  };
}

function toMore(value: unknown): { count: number; text: string } | null {
  const v = value as Record<string, unknown> | null;
  const count = num(v?.count);
  const text = str(v?.text);
  return count && count > 0 && text ? { count, text } : null;
}

function toScenes(value: unknown): ExplainerScene[] {
  if (!Array.isArray(value)) return [];
  const out: ExplainerScene[] = [];
  for (const item of value) {
    const v = item as Record<string, unknown>;
    const id = str(v?.id);
    const caption = str(v?.caption);
    if (!id || !caption || !isStage(v.stage)) continue;
    out.push({
      id,
      stage: v.stage,
      visual: (VISUALS as unknown[]).includes(v.visual)
        ? (v.visual as ExplainerVisual)
        : 'summary',
      caption,
    });
  }
  return out;
}

function toAudio(value: unknown): ExplainerAudio {
  const v = value as Record<string, unknown> | null;
  const token = str(v?.token);
  if (v?.available === true && token) return { available: true, token };
  return {
    available: false,
    reason: typeof v?.reason === 'string' ? v.reason : undefined,
  };
}

function toApplyRef(value: unknown): ExplainerApplyRef | null {
  const v = value as Record<string, unknown> | null;
  const id = str(v?.id);
  if (!id) return null;
  if (v?.type !== 'rule_preview' && v?.type !== 'settings_actions') return null;
  return { type: v.type, id };
}

export function parseExplainer(value: unknown): Explainer | null {
  const v = value as Record<string, unknown> | null;
  if (!v || typeof v !== 'object') return null;
  const id = str(v.id);
  const title = str(v.title);
  const diagram = toDiagram(v.diagram);
  if (!id || !title || !diagram) return null;
  const offerKind = str(v.offer_kind) ?? '';
  // v2 blocker decision: without a readable decision the card is dropped, never half-drawn
  const isDecision = offerKind === BLOCKER_DECISION_KIND;
  const decision = isDecision ? toDecision(v.decision) : null;
  if (isDecision && !decision) return null;
  // `sections` is the v1-safe projection; the structured v2 kinds come in
  // `sections_v2`. One list is rendered, never both (no double rendering).
  const sectionsV2 = decision ? toSections(v.sections_v2) : [];
  const sections = sectionsV2.length ? sectionsV2 : toSections(v.sections);
  if (!sections.length) return null;
  const effect = decision ? toEffect(v.effect) : null;
  const pending = decision ? v.pending === true : false;
  // phase A has no apply path for a decision: only a rule-writing operation may point at one
  const mayApply = !decision || (WRITING_OPERATIONS.includes(decision.operation) && !pending);
  const canApply = mayApply && v.can_apply === true;
  const applyRef = toApplyRef(v.apply_ref);
  const proven = gainProven(effect, pending);
  // the gain scene belongs to a positive touchless effect only; elsewhere it is neutral
  const scenes = toScenes(v.scenes).map((scene) =>
    decision && scene.visual === 'touchless_gain' && !proven
      ? { ...scene, visual: 'summary' as ExplainerVisual }
      : scene,
  );
  return {
    schema_version: num(v.schema_version) ?? 1,
    id,
    offer_id: str(v.offer_id) ?? id,
    offer_kind: offerKind,
    field: str(v.field) ?? '',
    field_label: str(v.field_label) ?? '',
    finding_id: str(v.finding_id) ?? '',
    language: str(v.language) ?? '',
    title,
    sections,
    visual: parseExplainerVisual(v.visual),
    diagram,
    result_model: str(v.result_model) ?? '',
    evidence: toEvidence(v.evidence),
    touchless_impact: toImpact(v.touchless_impact),
    scenes,
    audio: toAudio(v.audio),
    can_apply: canApply,
    // display-only: only an admin card may point at the apply card
    apply_ref: canApply ? applyRef : null,
    pending,
    decision,
    effect,
    more: decision ? toMore(v.more) : null,
    rank_score: num(v.rank_score) ?? 0,
    // a decision never changes the form; an offer only through its set_value card
    form_action: decision ? null : toFormAction(v.form_action),
  };
}

export function parseExplainers(value: unknown): Explainer[] {
  if (!Array.isArray(value)) return [];
  const out: Explainer[] = [];
  for (const item of value) {
    const parsed = parseExplainer(item);
    if (parsed && !out.some((known) => known.id === parsed.id)) {
      out.push(parsed);
    }
  }
  return out;
}

/** "Copy summary": title and sections only. */
export function explainerSummaryText(explainer: Explainer): string {
  return [explainer.title, ...explainer.sections.map((s) => s.text)].join(
    '\n\n',
  );
}

export interface AudioTiming {
  status: 'pending' | 'ready' | 'failed';
  audio_id?: string;
  scene_starts?: number[];
  duration?: number;
}

/** Index of the scene playing at `time`: the last start that is <= time. */
export function sceneIndexAt(starts: number[], time: number): number {
  let index = 0;
  for (let i = 0; i < starts.length; i += 1) {
    if (starts[i] <= time) index = i;
    else break;
  }
  return index;
}

export interface AlignedChar {
  ch: string;
  /** keep: in both values; del: only before (closes up); add: only after. */
  state: 'keep' | 'del' | 'add';
}

/**
 * Character alignment of two values (LCS), so the video can morph ONE value:
 * shared glyphs stay where they are at the same size, removed ones close up.
 */
export function alignValue(before: string, after: string): AlignedChar[] {
  const a = Array.from(before);
  const b = Array.from(after);
  const dp: number[][] = Array.from({ length: a.length + 1 }, () =>
    new Array(b.length + 1).fill(0),
  );
  for (let i = a.length - 1; i >= 0; i -= 1) {
    for (let j = b.length - 1; j >= 0; j -= 1) {
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);
    }
  }
  const out: AlignedChar[] = [];
  let i = 0;
  let j = 0;
  while (i < a.length || j < b.length) {
    if (i < a.length && j < b.length && a[i] === b[j]) {
      out.push({ ch: a[i], state: 'keep' });
      i += 1;
      j += 1;
    } else if (i < a.length && (j >= b.length || dp[i + 1][j] >= dp[i][j + 1])) {
      out.push({ ch: a[i], state: 'del' });
      i += 1;
    } else {
      out.push({ ch: b[j], state: 'add' });
      j += 1;
    }
  }
  return out;
}
